import java.util.*;

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> ans = new ArrayList<>();
        int n = s.length(), k = p.length();
        if (k > n) return ans;                 // 别忘了这行，否则 substring 越界

        char[] target = p.toCharArray();
        Arrays.sort(target);

        for (int i = 0; i <= n - k; i++) {
            char[] sub = s.substring(i, i + k).toCharArray();
            Arrays.sort(sub);
            // 排序后完全相同 = 字母构成相同 = 互为异位词
            if (Arrays.equals(sub, target)) ans.add(i);
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> ans = new ArrayList<>();
        int n = s.length(), k = p.length();
        if (k > n) return ans;

        int[] need = new int[26];
        for (char c : p.toCharArray()) need[c - 'a']++;

        int[] window = new int[26];
        for (int right = 0; right < n; right++) {
            window[s.charAt(right) - 'a']++;              // 进窗口
            if (right >= k) {
                window[s.charAt(right - k) - 'a']--;      // 出窗口，注意是 right-k
            }
            // 窗口满了才开始比较
            if (right >= k - 1 && Arrays.equals(window, need)) {
                ans.add(right - k + 1);
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> ans = new ArrayList<>();
        int n = s.length(), k = p.length();
        if (k > n) return ans;

        int[] need = new int[26];
        for (char c : p.toCharArray()) need[c - 'a']++;

        int[] window = new int[26];
        int diff = 0;
        for (int i = 0; i < 26; i++) if (need[i] != 0) diff++;   // 初始差异种类数

        for (int right = 0; right < n; right++) {
            int in = s.charAt(right) - 'a';
            if (window[in] == need[in]) diff++;   // 马上要不等了
            window[in]++;
            if (window[in] == need[in]) diff--;   // 又相等了

            if (right >= k) {
                int out = s.charAt(right - k) - 'a';
                if (window[out] == need[out]) diff++;
                window[out]--;
                if (window[out] == need[out]) diff--;
            }

            if (right >= k - 1 && diff == 0) ans.add(right - k + 1);
        }
        return ans;
    }
}
